prompt --application/pages/page_00010
begin
wwv_flow_imp_page.create_page(
 p_id=>10
,p_name=>'Detalle Bar'
,p_alias=>'DETALLE-BAR'
,p_step_title=>'Detalle Bar'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'(function () {',
'  const API_BASE = "https://taller-3-api.onrender.com/bares";',
'  const BAR_ITEM = "P10_BAR_ID";',
'',
'  function getBarId() {',
'    return parseInt(apex.item(BAR_ITEM).getValue(), 10);',
'  }',
'',
'  function escapeHtml(value) {',
'    if (value === null || value === undefined) return "";',
'    return String(value)',
'      .replaceAll("&", "&amp;")',
'      .replaceAll("<", "&lt;")',
'      .replaceAll(">", "&gt;")',
'      .replaceAll(''"'', "&quot;")',
'      .replaceAll("''", "&#039;");',
'  }',
'',
'  window.cargarComentarios = function () {',
'    const barId = getBarId();',
'',
'    fetch(`${API_BASE}/${barId}/comentarios`)',
'      .then(res => res.json())',
'      .then(data => {',
'        const container = document.getElementById("comentarios-container");',
'',
'        if (!data || data.length === 0) {',
unistr('          container.innerHTML = "<p>No hay comentarios a\00FAn. \00A1S\00E9 el primero!</p>";'),
'          return;',
'        }',
'',
'        container.innerHTML = data.map(c => `',
'          <div style="border:1px solid #ddd; border-radius:8px; padding:12px; margin-bottom:10px;">',
unistr('            <strong>${escapeHtml(c.autor || "An\00F3nimo")}</strong>'),
'            <span style="color:#888; font-size:0.85em; margin-left:10px;">',
'              ${c.date ? new Date(c.date).toLocaleDateString("es-CO") : ""}',
'            </span>',
'            <p style="margin-top:6px;">${escapeHtml(c.texto)}</p>',
'          </div>',
'        `).join("");',
'      })',
'      .catch(() => {',
'        document.getElementById("comentarios-container").innerHTML =',
'          "<p style=''color:red;''>Error cargando comentarios.</p>";',
'      });',
'  };',
'',
'  window.enviarComentario = function () {',
'    const barId = getBarId();',
'    const texto = apex.item("P10_COMENTARIO_TEXTO").getValue();',
'',
'    apex.message.clearErrors();',
'',
'    if (!texto.trim()) {',
'      apex.message.showErrors([',
'        {',
'          type: "error",',
'          location: "page",',
unistr('          message: "El comentario no puede estar vac\00EDo.",'),
'          unsafe: false',
'        }',
'      ]);',
'      return;',
'    }',
'',
'    fetch(`${API_BASE}/${barId}/comentarios`, {',
'      method: "POST",',
'      headers: {',
'        "Content-Type": "application/json"',
'      },',
'      body: JSON.stringify({',
'        bar_id: barId,',
'        texto: texto,',
'        autor: apex.env.APP_USER',
'      })',
'    })',
'      .then(res => res.json())',
'      .then(() => {',
'        apex.item("P10_COMENTARIO_TEXTO").setValue("");',
'        cargarComentarios();',
'      })',
'      .catch(() => {',
'        apex.message.showErrors([',
'          {',
'            type: "error",',
'            location: "page",',
'            message: "Error enviando el comentario.",',
'            unsafe: false',
'          }',
'        ]);',
'      });',
'  };',
'',
'  window.cargarEventos = function () {',
'    const barId = getBarId();',
'',
'    fetch(`${API_BASE}/${barId}/eventos`)',
'      .then(res => res.json())',
'      .then(data => {',
'        const container = document.getElementById("eventos-container");',
'',
'        if (!data || data.length === 0) {',
'          container.innerHTML = "<p>No hay eventos registrados para este bar.</p>";',
'          return;',
'        }',
'',
'        container.innerHTML = data.map(e => {',
'          const camposExtra = Object.entries(e)',
'            .filter(([k, v]) =>',
'              !["_id", "bar_id", "nombre", "fecha_creacion"].includes(k) &&',
'              v !== null &&',
'              v !== ""',
'            )',
'            .map(([k, v]) => `',
'              <li><strong>${escapeHtml(k)}:</strong> ${escapeHtml(v)}</li>',
'            `)',
'            .join("");',
'',
'          return `',
'            <div style="border:1px solid #ccc; border-radius:8px; padding:12px; margin-bottom:10px;">',
'              <h4 style="margin-top:0;">${escapeHtml(e.nombre)}</h4>',
'              <ul style="margin-bottom:6px;">',
'                ${camposExtra}',
'              </ul>',
'              <span style="color:#888; font-size:0.85em;">',
'                ${e.fecha_creacion ? new Date(e.fecha_creacion).toLocaleDateString("es-CO") : ""}',
'              </span>',
'            </div>',
'          `;',
'        }).join("");',
'      })',
'      .catch(() => {',
'        document.getElementById("eventos-container").innerHTML =',
'          "<p style=''color:red;''>Error cargando eventos.</p>";',
'      });',
'  };',
'',
'  function agregarSiTieneValor(obj, campo, itemName, convertirNumero = false) {',
'    const valor = apex.item(itemName).getValue();',
'',
'    if (valor !== null && valor !== undefined && String(valor).trim() !== "") {',
'      obj[campo] = convertirNumero ? Number(valor) : valor;',
'    }',
'  }',
'',
'  window.enviarEvento = function () {',
'    const barId = getBarId();',
'    const nombre = apex.item("P10_EVENTO_NOMBRE").getValue();',
'',
'    apex.message.clearErrors();',
'',
'    if (!nombre.trim()) {',
'      apex.message.showErrors([',
'        {',
'          type: "error",',
'          location: "page",',
'          message: "El nombre del evento es obligatorio.",',
'          unsafe: false',
'        }',
'      ]);',
'      return;',
'    }',
'',
'    const evento = {',
'      nombre: nombre',
'    };',
'',
'    agregarSiTieneValor(evento, "artista", "P10_EVENTO_ARTISTA");',
'    agregarSiTieneValor(evento, "cover", "P10_EVENTO_COVER", true);',
'    agregarSiTieneValor(evento, "cupos", "P10_EVENTO_CUPOS", true);',
'    agregarSiTieneValor(evento, "descuento", "P10_EVENTO_DESCUENTO");',
'    agregarSiTieneValor(evento, "hora_inicio", "P10_EVENTO_HORA_INICIO");',
'    agregarSiTieneValor(evento, "hora_fin", "P10_EVENTO_HORA_FIN");',
'',
'    fetch(`${API_BASE}/${barId}/eventos`, {',
'      method: "POST",',
'      headers: {',
'        "Content-Type": "application/json"',
'      },',
'      body: JSON.stringify(evento)',
'    })',
'      .then(res => res.json())',
'      .then(() => {',
'        apex.item("P10_EVENTO_NOMBRE").setValue("");',
'        apex.item("P10_EVENTO_ARTISTA").setValue("");',
'        apex.item("P10_EVENTO_COVER").setValue("");',
'        apex.item("P10_EVENTO_CUPOS").setValue("");',
'        apex.item("P10_EVENTO_DESCUENTO").setValue("");',
'        apex.item("P10_EVENTO_HORA_INICIO").setValue("");',
'        apex.item("P10_EVENTO_HORA_FIN").setValue("");',
'',
'        cargarEventos();',
'      })',
'      .catch(() => {',
'        apex.message.showErrors([',
'          {',
'            type: "error",',
'            location: "page",',
'            message: "Error enviando el evento.",',
'            unsafe: false',
'          }',
'        ]);',
'      });',
'  };',
'',
'  cargarComentarios();',
'  cargarEventos();',
'})();'))
,p_page_template_options=>'#DEFAULT#'
,p_protection_level=>'C'
,p_page_component_map=>'03'
,p_last_updated_by=>'JPABLO'
,p_last_upd_yyyymmddhh24miss=>'20260516225622'
);
